/**
 * Stock bubble chart + linked data table (D3.js v6).
 * Generated by scripts/build_app.py from assets/templates/visualization.js.
 *
 * Defaults (documented per the determinism rules):
 * - Chart viewBox is a fixed 760 x 640; the table sits beside it (flex row).
 * - Bubble area ~ market cap (d3.scaleSqrt); rows with no market cap (ETFs)
 *   get one uniform radius.
 * - Sector colors: d3.schemeCategory10 over sectors sorted alphabetically.
 * - Layout: d3.forceSimulation with forceX/forceY pulling each bubble to its
 *   sector's anchor (anchors packed tightly around the centre with
 *   d3.packSiblings) and forceCollide to prevent overlap. Initial positions
 *   are deterministic (no Math.random) and the simulation runs a fixed number
 *   of ticks synchronously, then stops: same input -> same picture.
 * - Tooltip (ticker, name, sector) only for non-ETF rows.
 * - Clicking a bubble highlights its table row and vice versa.
 */
(function () {
    'use strict';

    // Column mapping and data path, written by build_app.py.
    const CONFIG = /*__CONFIG__*/{
        dataFile: 'data/stock-descriptions.csv',
        columns: {ticker: 'ticker', name: 'full name', sector: 'sector',
                  marketCap: 'marketCap', country: 'country', website: 'website'},
        etfSector: 'ETF'
    }/*__END_CONFIG__*/;

    // Same rows embedded at build time: fallback when d3.csv cannot fetch
    // (opening index.html from file:// blocks fetch in Chromium).
    const EMBEDDED_ROWS = /*__EMBEDDED_ROWS__*/[]/*__END_ROWS__*/;

    const WIDTH = 760;
    const HEIGHT = 640;
    const PAD = 12;
    const TICKS = 400;

    const state = {selected: null, sortKey: null, sortAscending: true};

    // ---------- data ----------
    function loadRows() {
        return d3.csv(CONFIG.dataFile)
            .then(rows => (rows && rows.length ? rows : EMBEDDED_ROWS))
            .catch(() => EMBEDDED_ROWS);
    }

    function str(v) {
        return v === undefined || v === null ? '' : String(v).trim();
    }

    function normalize(raw, i) {
        const c = CONFIG.columns;
        const mcRaw = str(raw[c.marketCap]);
        const mc = mcRaw === '' ? NaN : +mcRaw;
        const d = {
            index: i,
            ticker: str(raw[c.ticker]),
            name: str(raw[c.name]),
            sector: str(raw[c.sector]) || 'Unknown',
            marketCap: isFinite(mc) && mc > 0 ? mc : null,
            country: c.country ? str(raw[c.country]) : '',
            website: c.website ? str(raw[c.website]) : ''
        };
        // ETF: sector says so, or the row has none of marketCap/country/website.
        d.isETF = d.sector.toUpperCase() === str(CONFIG.etfSector).toUpperCase() ||
            (d.marketCap === null && !d.country && !d.website);
        d.hasTooltip = !d.isETF;
        return d;
    }

    // ---------- formatting ----------
    function formatMarketCap(num) {
        if (num === null || num === undefined || num === '' || isNaN(num)) return '-';
        const abs = Math.abs(num);
        let out;
        if (abs >= 1e12) out = (abs / 1e12).toFixed(2) + 'T';
        else if (abs >= 1e9) out = (abs / 1e9).toFixed(2) + 'B';
        else if (abs >= 1e6) out = (abs / 1e6).toFixed(2) + 'M';
        else if (abs >= 1e3) out = (abs / 1e3).toFixed(2) + 'K';
        else out = abs.toFixed(2);
        return num < 0 ? '-' + out : out;
    }

    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, ch => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        }[ch]));
    }

    // ---------- scales ----------
    function sectorColor(sectors) {
        let range = d3.schemeCategory10.slice();
        if (sectors.length > range.length) {
            range = range.concat(d3.schemeSet3);
        }
        if (sectors.length > range.length) {
            range = sectors.map((s, i) => d3.interpolateRainbow(i / sectors.length));
        }
        return d3.scaleOrdinal().domain(sectors).range(range);
    }

    // Pick the largest radius so total bubble area ~ 42% of the chart area.
    function assignRadii(nodes) {
        const maxCap = d3.max(nodes, d => d.marketCap) || 1;
        const rMin = 14;  // smallest bubble still fits a readable ticker
        const target = WIDTH * HEIGHT * 0.42;
        const area = rMax => {
            const s = d3.scaleSqrt().domain([0, maxCap]).range([0, rMax]);
            const etfR = Math.max(rMin, rMax * 0.3);
            return d3.sum(nodes, d => {
                const r = d.marketCap === null ? etfR : Math.max(rMin, s(d.marketCap));
                return Math.PI * r * r;
            });
        };
        let lo = 12, hi = Math.min(WIDTH, HEIGHT) / 3;
        for (let k = 0; k < 40; k++) {
            const mid = (lo + hi) / 2;
            if (area(mid) > target) hi = mid; else lo = mid;
        }
        const rMax = lo;
        const scale = d3.scaleSqrt().domain([0, maxCap]).range([0, rMax]);
        const etfR = Math.max(rMin, rMax * 0.3);  // uniform size for ETFs
        nodes.forEach(d => {
            d.radius = d.marketCap === null ? etfR : Math.max(rMin, scale(d.marketCap));
        });
    }

    // Sector anchors: one circle per sector sized by its members' area,
    // packed tightly (packSiblings) and centred on the chart.
    function sectorAnchors(nodes, sectors) {
        const groups = sectors.map(s => {
            const members = nodes.filter(d => d.sector === s);
            const r = Math.sqrt(d3.sum(members, d => d.radius * d.radius) / 0.62) + 6;
            return {sector: s, r: r};
        });
        const packed = groups.slice().sort((a, b) => d3.descending(a.r, b.r) ||
            d3.ascending(a.sector, b.sector));
        d3.packSiblings(packed);
        const enclose = d3.packEnclose(packed);
        const anchors = {};
        packed.forEach(g => {
            anchors[g.sector] = {x: WIDTH / 2 + g.x - enclose.x, y: HEIGHT / 2 + g.y - enclose.y};
        });
        return anchors;
    }

    function runLayout(nodes, anchors) {
        // Deterministic start: sunflower spiral around each sector anchor.
        const golden = Math.PI * (3 - Math.sqrt(5));
        const seen = {};
        nodes.forEach(d => {
            const k = seen[d.sector] = (seen[d.sector] || 0) + 1;
            const a = anchors[d.sector];
            d.x = a.x + 6 * Math.sqrt(k) * Math.cos(k * golden);
            d.y = a.y + 6 * Math.sqrt(k) * Math.sin(k * golden);
        });

        const sim = d3.forceSimulation(nodes)
            .force('x', d3.forceX(d => anchors[d.sector].x).strength(0.12))
            .force('y', d3.forceY(d => anchors[d.sector].y).strength(0.12))
            .force('collide', d3.forceCollide(d => d.radius + 1.5).strength(1).iterations(3))
            .stop();
        for (let i = 0; i < TICKS; i++) sim.tick();

        // Settle residual overlap with collision only.
        sim.force('x', null).force('y', null).alpha(0.3);
        for (let i = 0; i < 120; i++) sim.tick();
        sim.stop();

        // Uniformly scale and centre the result into the viewBox.
        // Uniform scaling keeps the no-overlap guarantee.
        const x0 = d3.min(nodes, d => d.x - d.radius), x1 = d3.max(nodes, d => d.x + d.radius);
        const y0 = d3.min(nodes, d => d.y - d.radius), y1 = d3.max(nodes, d => d.y + d.radius);
        const s = Math.min((WIDTH - 2 * PAD) / (x1 - x0), (HEIGHT - 2 * PAD) / (y1 - y0), 1.6);
        const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
        nodes.forEach(d => {
            d.x = WIDTH / 2 + (d.x - cx) * s;
            d.y = HEIGHT / 2 + (d.y - cy) * s;
            d.radius = d.radius * s;
        });
    }

    // ---------- tooltip ----------
    const tooltip = () => d3.select('#tooltip');

    function showTooltip(event, d) {
        if (!d.hasTooltip) {          // ETFs: no tooltip
            hideTooltip();
            return;
        }
        tooltip()
            .classed('visible', true)
            .html(`<strong>${escapeHtml(d.ticker)}</strong><br/>` +
                  `${escapeHtml(d.name || 'N/A')}<br/>` +
                  `Sector: ${escapeHtml(d.sector)}`);
        moveTooltip(event);
    }

    function moveTooltip(event) {
        if (!tooltip().classed('visible')) return;
        tooltip()
            .style('left', (event.pageX + 12) + 'px')
            .style('top', (event.pageY - 12) + 'px');
    }

    function hideTooltip() {
        tooltip().classed('visible', false);
    }

    // ---------- linked selection ----------
    function select(ticker) {
        state.selected = ticker;
        d3.selectAll('.bubble')
            .classed('selected', d => d.ticker === ticker)
            .classed('highlighted', d => d.ticker === ticker);
        d3.selectAll('#stock-table tbody tr')
            .classed('selected', d => d.ticker === ticker)
            .classed('highlighted', d => d.ticker === ticker);
        const row = document.querySelector(`#stock-table tbody tr[data-ticker="${CSS.escape(ticker)}"]`);
        if (row && row.scrollIntoView) row.scrollIntoView({block: 'nearest'});
        // Raise the chosen bubble so its outline is not hidden by neighbours.
        d3.selectAll('.bubble-node').filter(d => d.ticker === ticker).raise();
    }

    // ---------- chart ----------
    function drawChart(nodes, sectors, color) {
        const legend = d3.select('#legend');
        legend.selectAll('*').remove();
        const items = legend.selectAll('.legend-item')
            .data(sectors)
            .join('div')
            .attr('class', 'legend-item')
            .attr('data-sector', d => d);
        items.append('span').attr('class', 'legend-swatch').style('background-color', d => color(d));
        items.append('span').attr('class', 'legend-label').text(d => d);

        const svg = d3.select('#chart').append('svg')
            .attr('id', 'bubble-chart')
            .attr('viewBox', `0 0 ${WIDTH} ${HEIGHT}`)
            .attr('preserveAspectRatio', 'xMidYMid meet')
            .attr('role', 'img')
            .attr('aria-label', 'Bubble chart of stocks sized by market cap and clustered by sector');

        const node = svg.append('g').attr('class', 'bubbles')
            .selectAll('g')
            .data(nodes, d => d.ticker)
            .join('g')
            .attr('class', d => 'bubble-node' + (d.isETF ? ' etf' : ''))
            .attr('transform', d => `translate(${d.x.toFixed(2)},${d.y.toFixed(2)})`);

        node.append('circle')
            .attr('class', d => 'bubble' + (d.isETF ? ' etf' : ''))
            .attr('id', d => 'bubble-' + d.ticker)
            .attr('data-ticker', d => d.ticker)
            .attr('data-sector', d => d.sector)
            .attr('r', d => d.radius.toFixed(2))
            .attr('fill', d => color(d.sector))
            .on('mouseover', showTooltip)
            .on('mousemove', moveTooltip)
            .on('mouseout', hideTooltip)
            .on('click', (event, d) => select(d.ticker));

        node.append('text')
            .attr('class', 'bubble-label')
            .attr('text-anchor', 'middle')
            .attr('dy', '0.35em')
            // Dark text on light fills (extended palettes), white otherwise.
            .style('fill', d => d3.lab(color(d.sector)).l > 72 ? '#222' : '#fff')
            .style('font-size', d => {
                const len = Math.max(1, d.ticker.length);
                // ~0.72em per bold capital (M and W are wide); keep 15% side margin.
                return Math.max(6, Math.min(16, d.radius * 0.8, (1.55 * d.radius) / (len * 0.72))).toFixed(1) + 'px';
            })
            .text(d => d.ticker);
    }

    // ---------- table ----------
    const COLUMNS = [
        {key: 'ticker', label: 'Ticker symbol', format: v => v},
        {key: 'name', label: 'Full company name', format: v => v},
        {key: 'sector', label: 'Sector', format: v => v},
        {key: 'marketCap', label: 'Market cap', format: formatMarketCap, numeric: true}
    ];

    function drawTable(rows) {
        const table = d3.select('#table-container').append('table')
            .attr('id', 'stock-table')
            .attr('class', 'data-table');

        table.append('thead').append('tr')
            .selectAll('th')
            .data(COLUMNS)
            .join('th')
            .attr('class', c => c.numeric ? 'numeric' : null)
            .attr('title', 'Click to sort')
            .text(c => c.label)
            .on('click', (event, c) => sortBy(c.key));

        const tbody = table.append('tbody');

        function render(data) {
            const tr = tbody.selectAll('tr')
                .data(data, d => d.ticker)
                .join('tr')
                .attr('data-ticker', d => d.ticker)
                .attr('id', d => 'row-' + d.ticker)
                .classed('etf', d => d.isETF)
                .classed('selected', d => d.ticker === state.selected)
                .classed('highlighted', d => d.ticker === state.selected)
                .on('click', (event, d) => select(d.ticker));
            tr.order();
            tr.selectAll('td')
                .data(d => COLUMNS.map(c => ({c: c, v: d[c.key]})))
                .join('td')
                .attr('class', x => x.c.numeric ? 'numeric' : null)
                .text(x => x.c.format(x.v));
        }

        function sortBy(key) {
            state.sortAscending = state.sortKey === key ? !state.sortAscending : true;
            state.sortKey = key;
            const dir = state.sortAscending ? 1 : -1;
            const sorted = rows.slice().sort((a, b) => {
                const av = a[key], bv = b[key];
                if (key === 'marketCap') {
                    // Missing values always last.
                    if (av === null && bv === null) return a.index - b.index;
                    if (av === null) return 1;
                    if (bv === null) return -1;
                    return dir * (av - bv) || a.index - b.index;
                }
                return dir * String(av).localeCompare(String(bv)) || a.index - b.index;
            });
            render(sorted);
        }

        render(rows);  // default: file order
    }

    // ---------- main ----------
    loadRows().then(raw => {
        const rows = raw.map(normalize).filter(d => d.ticker !== '');
        const sectors = Array.from(new Set(rows.map(d => d.sector))).sort(d3.ascending);
        const color = sectorColor(sectors);
        const nodes = rows.slice().sort((a, b) =>
            d3.ascending(a.sector, b.sector) ||
            d3.descending(a.marketCap || 0, b.marketCap || 0) ||
            d3.ascending(a.ticker, b.ticker));
        assignRadii(nodes);
        runLayout(nodes, sectorAnchors(nodes, sectors));
        drawChart(nodes, sectors, color);
        drawTable(rows);
        document.body.setAttribute('data-ready', 'true');
    });
})();
